SELECT count(*) FROM public.chartevents chartevents WHERE (EXISTS (SELECT 1 FROM public.admissions a, public.drgcodes g, public.services s WHERE a.hadm_id = chartevents.hadm_id AND g.hadm_id = a.hadm_id AND g.drg_type = 'APR' AND g.drg_severity >= 3 AND s.hadm_id = a.hadm_id AND s.curr_service = 'MED') OR EXISTS (SELECT 1 FROM public.procedureevents pe, public.d_items di WHERE pe.stay_id = chartevents.stay_id AND chartevents.charttime >= pe.starttime AND chartevents.charttime <= pe.endtime AND di.itemid = pe.itemid AND di.label = 'Invasive Ventilation')) AND NOT EXISTS (SELECT 1 FROM public.admissions a, public.diagnoses_icd d, public.d_icd_diagnoses dd WHERE a.hadm_id = chartevents.hadm_id AND d.hadm_id = a.hadm_id AND (d.icd_code = 'F329' OR d.icd_code = '311') AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version);
